#!/usr/bin/env node
/** Red test from a reviewer probe (workflows/dev-loop.js). Generated by Claude Code at the user's request. */
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { run, ARGS_M, review, impl, gate } from './dev-loop.harness.mjs';

test('given a request hard-wrapped inside a negated sentence, when the judge quotes the last line, then the implementer gets the whole sentence', async () => {
  // Given
  const q = { text: 'Drop the orders table?', default: 'no', why: 'unsaid', reversible: false, axis: 'data' };
  const args = { ...ARGS_M, request: 'Fix the lookup.\nWe must never\ndrop the orders table.' };
  const judge = () => ({ judgments: [{ text: q.text, status: 'answered', answer: 'drop the orders table', quote: 'drop the orders table' }] });
  // When
  const { calls } = await run(args, [review([])], [impl({ gate: gate(), questions: [q] }), impl({ gate: gate() })], { judge });
  // Then
  const second = calls.filter(c => c.opts.agentType === 'implementer')[1];
  assert.match(second?.prompt ?? '', /Drop the orders table\? -> We must never drop the orders table\./);
});
